1	import Link from "next/link";
2	import { requireArea } from "@/lib/rbac";
3	import { db } from "@/lib/db";
4	import { PageHeader, StatCard, fmtMoney } from "@/components/ui/primitives";
5	import { AreaChart, Donut } from "@/components/ui/charts";
6	import { REVENUE_WHERE, serverMonthlyCents } from "@/lib/admin-metrics";
7	
8	export const dynamic = "force-dynamic";
9	
10	const PLAN_COLORS = ["#8a70fb", "#3b82f6", "#34d399", "#fbbf24", "#f472b6", "#22d3ee", "#a3e635", "#fb7185"];
11	
12	function monthKey(d: Date): string {
13	  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}`;
14	}
15	
16	export default async function AdminAnalytics() {
17	  await requireArea("analytics");
18	
19	  const now = new Date();
20	  const since30d = new Date(Date.now() - 30 * 86400_000);
21	  const sixMonthsAgo = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 5, 1));
22	  const twelveWeeksAgo = new Date(Date.now() - 12 * 7 * 86400_000);
23	
24	  const [charges6mo, signups, activeServers, deletions30d, spend30d, firstUser] = await Promise.all([
25	    db.walletTransaction.findMany({
26	      // Earned revenue only — REVENUE_WHERE drops refunds / affiliate cash-outs /
27	      // admin debits, which are also negative rows and would inflate every month.
28	      where: { ...REVENUE_WHERE, createdAt: { gte: sixMonthsAgo } },
29	      select: { amountCents: true, createdAt: true },
30	    }),
31	    db.user.findMany({
32	      where: { createdAt: { gte: twelveWeeksAgo } },
33	      select: { createdAt: true },
34	    }),
35	    db.server.findMany({
36	      where: { status: { notIn: ["DELETING"] } },
37	      include: {
38	        plan: { select: { id: true, name: true, priceCents: true } },
39	        // Needed to price game servers at their flat rate in serverMonthlyCents.
40	        gamePlan: { select: { priceCents: true, termMonths: true } },
41	        user: { select: { id: true, email: true, name: true } },
42	      },
43	    }),
44	    db.auditLog.count({ where: { action: "server.delete", createdAt: { gte: since30d } } }),
45	    db.walletTransaction.aggregate({
46	      where: { ...REVENUE_WHERE, createdAt: { gte: since30d } },
47	      _sum: { amountCents: true },
48	    }),
49	    db.user.findFirst({ orderBy: { createdAt: "asc" }, select: { createdAt: true } }),
50	  ]);
51	
52	  // Revenue by month (last 6 calendar months)
53	  const monthKeys: string[] = [];
54	  const revByMonth = new Map<string, number>();
55	  for (let i = 5; i >= 0; i--) {
56	    const k = monthKey(new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - i, 1)));
57	    monthKeys.push(k);
58	    revByMonth.set(k, 0);
59	  }
60	  for (const tx of charges6mo) {
61	    const k = monthKey(tx.createdAt);
62	    if (revByMonth.has(k)) revByMonth.set(k, (revByMonth.get(k) ?? 0) + Math.abs(tx.amountCents));
63	  }
64	  const revSeries = monthKeys.map((k) => (revByMonth.get(k) ?? 0) / 100);
65	
66	  // Signups by week (last 12 weeks)
67	  const weekBuckets = Array.from({ length: 12 }, () => 0);
68	  for (const u of signups) {
69	    const weeksAgo = Math.floor((Date.now() - u.createdAt.getTime()) / (7 * 86400_000));
70	    if (weeksAgo >= 0 && weeksAgo < 12) weekBuckets[11 - weeksAgo]++;
71	  }
72	
73	  // Plan distribution
74	  const byPlan = new Map<string, { name: string; count: number }>();
75	  for (const s of activeServers) {
76	    const cur = byPlan.get(s.plan.id) ?? { name: s.plan.name, count: 0 };
77	    cur.count++;
78	    byPlan.set(s.plan.id, cur);
79	  }
80	  const planEntries = [...byPlan.values()].sort((a, b) => b.count - a.count);
81	
82	  // ARPU
83	  const revenue30dCents = -(spend30d._sum.amountCents ?? 0);
84	  const activeCustomers = new Set(activeServers.map((s) => s.user.id)).size;
85	  const arpuCents = activeCustomers > 0 ? Math.round(revenue30dCents / activeCustomers) : 0;
86	
87	  // Top customers by committed monthly spend (active paid servers)
88	  const byCustomer = new Map<string, { email: string; name: string; mrrCents: number; servers: number }>();
89	  for (const s of activeServers) {
90	    const cur = byCustomer.get(s.user.id) ?? { email: s.user.email, name: s.user.name, mrrCents: 0, servers: 0 };
91	    cur.servers++;
92	    // Priced the billing engine's way (game plans flat, term per-month, suspended
93	    // at zero, free at zero). Was `plan.priceCents`, which overstated game servers
94	    // and long-term customers and billed suspended machines that are never charged.
95	    cur.mrrCents += serverMonthlyCents(s);
96	    byCustomer.set(s.user.id, cur);
97	  }
98	  const topCustomers = [...byCustomer.entries()]
99	    .sort((a, b) => b[1].mrrCents - a[1].mrrCents)
100	    .slice(0, 8);
101	
102	  const platformAgeDays = firstUser ? Math.floor((Date.now() - firstUser.createdAt.getTime()) / 86400_000) : 0;
103	  const shortHistory = platformAgeDays < 30;
104	
105	  return (
106	    <div className="space-y-6">
107	      <PageHeader
108	        title="Business analytics"
109	        sub={
110	          shortHistory
111	            ? `All figures since launch (${platformAgeDays}d of history) — trends firm up as data accrues.`
112	            : "Revenue, growth and customer metrics from live platform data."
113	        }
114	      />
115	
116	      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
117	        <StatCard label="Revenue · last 30d" value={fmtMoney(revenue30dCents)} delta={shortHistory ? "since launch" : "trailing 30 days"} />
118	        <StatCard
119	          label="ARPU · 30d"
120	          value={fmtMoney(arpuCents)}
121	          delta={`across ${activeCustomers} active customer${activeCustomers === 1 ? "" : "s"}`}
122	        />
123	        <StatCard
124	          label="Servers deleted · 30d"
125	          value={String(deletions30d)}
126	          delta={deletions30d === 0 ? "no churn signal" : "churn proxy (delete actions)"}
127	          deltaGood={deletions30d === 0}
128	        />
129	        <StatCard label="New signups · 12w" value={String(signups.length)} spark={weekBuckets} sparkColor="#3b82f6" />
130	      </div>
131	
132	      <div className="grid gap-4 xl:grid-cols-2">
133	        <div className="card">
134	          <h2 className="mb-1 font-semibold">Revenue by month</h2>
135	          <p className="mb-3 text-xs text-slate-500">
136	            Wallet charges (orders + renewals), grouped by calendar month{shortHistory ? " — history starts at launch" : ""}.
137	          </p>
138	          <AreaChart
139	            id="rev-month"
140	            series={[{ name: "Revenue $", data: revSeries, color: "#34d399" }]}
141	            height={200}
142	            yLabel={(v) => `$${v.toFixed(0)}`}
143	            xLabels={monthKeys.map((k) => k.slice(5))}
144	          />
145	        </div>
146	
147	        <div className="card">
148	          <h2 className="mb-1 font-semibold">Customer signups by week</h2>
149	          <p className="mb-3 text-xs text-slate-500">New accounts registered per week, last 12 weeks.</p>
150	          <AreaChart
151	            id="signups-week"
152	            series={[{ name: "Signups", data: weekBuckets, color: "#3b82f6" }]}
153	            height={200}
154	            yLabel={(v) => v.toFixed(0)}
155	            xLabels={["-12w", "-9w", "-6w", "-3w", "now"]}
156	          />
157	        </div>
158	      </div>
159	
160	      <div className="grid gap-4 xl:grid-cols-3">
161	        <div className="card">
162	          <h2 className="mb-1 font-semibold">Plan distribution</h2>
163	          <p className="mb-4 text-xs text-slate-500">Active servers per plan (free and paid).</p>
164	          {planEntries.length === 0 ? (
165	            <p className="py-8 text-center text-sm text-slate-500">No active servers yet.</p>
166	          ) : (
167	            <div className="flex items-center gap-6">
168	              <Donut
169	                segments={planEntries.map((p, i) => ({ value: p.count, color: PLAN_COLORS[i % PLAN_COLORS.length] }))}
170	                centerLabel={String(activeServers.length)}
171	                centerSub="servers"
172	              />
173	              <ul className="space-y-2 text-sm">
174	                {planEntries.map((p, i) => (
175	                  <li key={p.name} className="flex items-center gap-2">
176	                    <span
177	                      className="h-2.5 w-2.5 rounded-full"
178	                      style={{ background: PLAN_COLORS[i % PLAN_COLORS.length] }}
179	                    />
180	                    <span>{p.name}</span>
181	                    <span className="text-xs text-slate-500">×{p.count}</span>
182	                  </li>
183	                ))}
184	              </ul>
185	            </div>
186	          )}
187	        </div>
188	
189	        <div className="card p-0 xl:col-span-2">
190	          <div className="px-5 pt-5">
191	            <h2 className="font-semibold">Top customers by monthly spend</h2>
192	            <p className="mt-1 text-xs text-slate-500">
193	              Committed MRR from each customer&apos;s active paid servers (free servers excluded).
194	            </p>
195	          </div>
196	          {topCustomers.length === 0 ? (
197	            <p className="px-5 py-8 text-sm text-slate-500">No customers with servers yet.</p>
198	          ) : (
199	            <div className="overflow-x-auto pt-3">
200	              <table className="table-shell">
201	                <thead>
202	                  <tr>
203	                    <th>Customer</th>
204	                    <th>Servers</th>
205	                    <th className="text-right">Monthly spend</th>
206	                  </tr>
207	                </thead>
208	                <tbody>
209	                  {topCustomers.map(([id, c]) => (
210	                    <tr key={id}>
211	                      <td>
212	                        <Link href={`/admin/users/${id}`} className="font-medium hover:text-brand-300">
213	                          {c.name}
214	                        </Link>
215	                        <span className="ml-2 text-xs text-slate-500">{c.email}</span>
216	                      </td>
217	                      <td>{c.servers}</td>
218	                      <td className="text-right font-medium">
219	                        {c.mrrCents > 0 ? `${fmtMoney(c.mrrCents)}/mo` : <span className="text-slate-500">free only</span>}
220	                      </td>
221	                    </tr>
222	                  ))}
223	                </tbody>
224	              </table>
225	            </div>
226	          )}
227	        </div>
228	      </div>
229	    </div>
230	  );
231	}
