1	import Link from "next/link";
2	import { requireArea } from "@/lib/rbac";
3	import { db } from "@/lib/db";
4	import { PageHeader, Badge, fmtMoney, timeAgo } from "@/components/ui/primitives";
5	import { SuspendUserButton } from "@/components/AdminControls";
6	import { ImpersonateButton } from "@/components/admin/ImpersonateButton";
7	import { BulkTable, type BulkRow } from "@/components/admin/BulkTable";
8	import { bulkSuspendUsers } from "@/lib/actions-admin-billing";
9	import { paginate, pageHref } from "@/lib/pagination";
10	import { fleetMrrCents } from "@/lib/admin-metrics";
11	
12	export const dynamic = "force-dynamic";
13	
14	const PER_PAGE = 25;
15	
16	export default async function AdminUsers({
17	  searchParams,
18	}: {
19	  searchParams: Promise<{ q?: string; page?: string }>;
20	}) {
21	  // See the note on /admin/users/[id]: `clients` admits SUPPORT, but Impersonate
22	  // and Suspend are `requireAdmin()` actions. Render only what the role can use.
23	  const me = await requireArea("clients");
24	  const canAct = me.role === "ADMIN";
25	  const sp = await searchParams;
26	  const query = (sp.q ?? "").trim();
27	
28	  const where = query
29	    ? {
30	        OR: [
31	          { email: { contains: query, mode: "insensitive" as const } },
32	          { name: { contains: query, mode: "insensitive" as const } },
33	        ],
34	      }
35	    : undefined;
36	
37	  const total = await db.user.count({ where });
38	  const pg = paginate(sp, total, PER_PAGE);
39	  const users = await db.user.findMany({
40	    where,
41	    include: {
42	      servers: {
43	        where: { status: { notIn: ["DELETING"] } },
44	        select: {
45	          isFree: true,
46	          status: true,
47	          termMonths: true,
48	          plan: { select: { priceCents: true } },
49	          gamePlan: { select: { priceCents: true, termMonths: true } },
50	        },
51	      },
52	    },
53	    orderBy: { createdAt: "desc" },
54	    skip: pg.skip,
55	    take: pg.take,
56	  });
57	
58	  const exportHref = `/api/admin/export?type=users${query ? `&q=${encodeURIComponent(query)}` : ""}`;
59	
60	  const rows: BulkRow[] = users.map((u) => {
61	    const mrr = fleetMrrCents(u.servers);
62	    return {
63	      id: u.id,
64	      selectable: u.role !== "ADMIN",
65	      cells: [
66	        <span key="c">
67	          <Link href={`/admin/users/${u.id}`} className="font-medium hover:text-brand-300">
68	            {u.name}
69	          </Link>
70	          <span className="ml-2 text-xs text-slate-500">{u.email}</span>
71	          {u.suspended && (
72	            <span className="ml-2">
73	              <Badge tone="red">suspended</Badge>
74	            </span>
75	          )}
76	        </span>,
77	        <Badge key="r" tone={u.role === "ADMIN" ? "brand" : "slate"}>{u.role.toLowerCase()}</Badge>,
78	        u.servers.length,
79	        fmtMoney(u.balanceCents),
80	        mrr > 0 ? `${fmtMoney(mrr)}/mo` : <span key="m" className="text-slate-500">—</span>,
81	        <span key="j" className="text-xs text-slate-400">{timeAgo(u.createdAt)}</span>,
82	        <div key="a" className="flex items-center justify-end gap-2">
83	          <Link href={`/admin/users/${u.id}`} className="btn-ghost py-1 text-xs">
84	            View →
85	          </Link>
86	          {canAct && u.role !== "ADMIN" && <ImpersonateButton userId={u.id} email={u.email} small />}
87	          {canAct && u.role !== "ADMIN" && <SuspendUserButton userId={u.id} suspended={u.suspended} />}
88	        </div>,
89	      ],
90	    };
91	  });
92	
93	  return (
94	    <div className="space-y-6">
95	      <PageHeader title="Clients" sub={`${total} account${total === 1 ? "" : "s"}${query ? ` matching “${query}”` : ""}`}>
96	        <form method="GET" className="flex items-center gap-2">
97	          <input
98	            className="input w-64 py-2"
99	            type="search"
100	            name="q"
101	            placeholder="Search email or name…"
102	            defaultValue={query}
103	          />
104	          <button className="btn-secondary py-2">Search</button>
105	          {query && (
106	            <Link href="/admin/users" className="btn-ghost py-2 text-xs">
107	              Clear
108	            </Link>
109	          )}
110	        </form>
111	      </PageHeader>
112	
113	      <div className="card p-0">
114	        <BulkTable
115	          columns={[
116	            { header: "Client" },
117	            { header: "Role" },
118	            { header: "Servers" },
119	            { header: "Balance" },
120	            { header: "Monthly spend" },
121	            { header: "Joined" },
122	            { header: "Actions", className: "text-right" },
123	          ]}
124	          rows={rows}
125	          exportHref={exportHref}
126	          minWidth={860}
127	          empty="No clients match this search."
128	          actions={
129	            canAct
130	              ? [
131	                  {
132	                    label: "Suspend",
133	                    danger: true,
134	                    // State the consequence, not the verb. Suspension logs the
135	                    // account out immediately and blocks sign-in; their servers
136	                    // keep running and keep costing us until someone unsuspends.
137	                    confirm:
138	                      "Suspend the selected clients?\n\nEach one is signed out immediately and cannot log back in until unsuspended. Their servers keep running and are not touched.",
139	                    run: bulkSuspendUsers,
140	                  },
141	                ]
142	              : []
143	          }
144	        />
145	
146	        <div className="flex items-center justify-between gap-3 px-5 py-4 text-xs text-slate-500">
147	          <span>
148	            Page {pg.page} of {pg.pages} · {total} client{total === 1 ? "" : "s"}
149	          </span>
150	          <div className="flex items-center gap-2">
151	            {pg.page > 1 && (
152	              <Link href={pageHref("/admin/users", { q: query }, pg.page - 1)} className="btn-ghost py-1 text-xs">
153	                ← Prev
154	              </Link>
155	            )}
156	            {pg.page < pg.pages && (
157	              <Link href={pageHref("/admin/users", { q: query }, pg.page + 1)} className="btn-ghost py-1 text-xs">
158	                Next →
159	              </Link>
160	            )}
161	          </div>
162	        </div>
163	      </div>
164	
165	      <p className="text-xs text-slate-500">
166	        Wallet credits are issued from a client&apos;s profile page. Monthly spend is the committed MRR of the
167	        client&apos;s active paid servers. Select rows to bulk-suspend or export the filtered set to CSV.
168	      </p>
169	    </div>
170	  );
171	}
